import pathlib,json,numpy as np,csv,io
P=pathlib.Path(__file__).resolve().parent;D=json.loads((P/'migracao-brasil-dados.json').read_text())
a=np.sum([s['first'] for s in D['states']],axis=0);b=np.sum([s['second'] for s in D['states']],axis=0);m=np.sum([s['matrix'] for s in D['states']],axis=0);alt=np.sum([s['independence'] for s in D['states']],axis=0)
assert np.max(np.abs(m.sum(axis=1)-a))<1e-5;assert np.max(np.abs(m.sum(axis=0)-b))<1e-5
for s in D['states']:
 for i,c in enumerate(D['codes']):
  for j in range(2):assert sum(s['histograms'][c][j]['votos_origem'])==round(s['first'][i])
D['audit']={'sections_evaluated':sum(s['total_sections'] for s in D['states']),'sections_included':sum(s['included_sections'] for s in D['states']),'strictly_comparable_sections':sum(s['strictly_comparable_sections'] for s in D['states']),'max_national_row_residual':float(np.max(np.abs(m.sum(axis=1)-a))),'max_national_column_residual':float(np.max(np.abs(m.sum(axis=0)-b))),'histogram_vote_weights_reconciled':True,'hypothesis':'Every included section is treated as a common accounting universe. Matching individual electors has not been established.'}
(P/'migracao-brasil-dados.json').write_text(json.dumps(D,ensure_ascii=False,separators=(',',':'))+'\n')
with (P/'migracao-brasil-por-candidato.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f,delimiter=';');w.writerow(['recorte','candidato','numero','base_1t','para_flavio_simulado','pct_para_flavio','para_lula_simulado','pct_para_lula','outros_destinos_simulados'])
 for name,aa,mm in [('BR+ZZ',a,m)]+[(s['uf'],s['first'],s['matrix']) for s in D['states']]:
  for i,c in enumerate(D['codes']):
   base=aa[i];mrow=mm[i];w.writerow([name,D['origins'][i],c,round(base),round(mrow[1],6),round(100*mrow[1]/base,6) if base else '',round(mrow[0],6),round(100*mrow[0]/base,6) if base else '',round(sum(mrow[2:]),6)])
html=r'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Brasil · fluxos simulados entre turnos</title><style>
body{margin:0;background:#eef3f6;color:#172d3e;font:15px system-ui}main{max-width:1400px;margin:auto;padding:22px}header,section{background:white;padding:24px;margin:0 0 18px;border-radius:14px}h1{margin:5px 0}h2{font-size:22px}p,li{line-height:1.6}.warn{border-left:5px solid #d58c17;background:#fff6e4;padding:16px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%}th,td{padding:12px 8px;border-bottom:1px solid #dce4eb;text-align:right;white-space:nowrap}td:first-child,th:first-child{text-align:left}small{color:#526777;line-height:1.6}.controls{display:flex;flex-wrap:wrap;gap:16px;margin:18px 0}select,button{font:inherit;padding:10px;border:1px solid #b2c1ce;border-radius:8px;background:white}label{display:flex;align-items:center;gap:8px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:18px}.card{border:1px solid #dbe4eb;padding:16px;border-radius:12px}.card h3{margin-top:0}svg{width:100%;height:auto}.kpis{display:flex;flex-wrap:wrap;gap:24px}.kpis b{display:block;font-size:26px}.red{color:#b32235}.green{color:#087549}a{color:#075985}@media(max-width:600px){main{padding:10px}header,section{padding:16px}}
</style><main><header><small>ANÁLISE ECOLÓGICA · BASE 2026 DO REPOSITÓRIO</small><h1>Dos votos de cada candidato, quanto foi alocado para cada finalista?</h1><p>Somatório de cenários calculados seção por seção. Brasil, 27 UFs e exterior separado. Percentual = fluxo simulado para o destino ÷ votos da candidatura no primeiro turno.</p><div class="warn"><b>Simulação contábil, sem identificação individual.</b> A tabela não comprova como eleitores votaram. O cenário principal maximiza permanência dentro de cada seção e reparte proporcionalmente os fluxos restantes. Isso favorece retenção dos finalistas por construção. As fontes derivadas do repositório não foram autenticadas novamente no TSE nesta execução.</div></header>
<section><h2>Cobertura e conferência</h2><div id="kpis" class="kpis"></div><p id="audit"></p><details><summary>Hipóteses e limites de interpretação</summary><ol><li>Primeiro preserva-se o máximo possível dos votos de Lula, Flávio, brancos, nulos e abstenção em suas categorias.</li><li>A oferta e a demanda restantes são alocadas proporcionalmente dentro de cada seção. Os candidatos eliminados não recebem preferências ideológicas próprias: a diferença entre suas taxas nacionais decorre da distribuição geográfica dos votos.</li><li>O cenário alternativo de independência não preserva fidelidade; ele demonstra quanto as respostas dependem da hipótese escolhida. Não é uma previsão rival nem um intervalo de confiança.</li><li>As 43 seções excluídas têm dados não conferidos. As demais foram incluídas no cenário amplo, mesmo com alterações cadastrais; ajustes não são eleitores identificados. O recorte estrito exige mesmo local, aptos iguais positivos e nenhum resíduo de universo, mas isso também não comprova identidade dos eleitores.</li><li>Limites mínimo–máximo são de Fréchet condicionados ao universo comum por seção. Extremos de células diferentes não precisam ser simultaneamente possíveis.</li><li>Não há calibração probabilística ou evidência individual de transferência. 100% da apuração não elimina a não identificação dos fluxos.</li></ol></details></section>
<section><h2>Resultado por candidato · votos do primeiro turno como denominador</h2><div class="controls"><label>Território <select id="territory"><option value="BR">Brasil + exterior</option><option value="BRonly">Brasil sem exterior</option></select></label><label>Cenário <select id="model"><option value="matrix">Permanência máxima + rateio residual</option><option value="independence">Independência por seção · sensibilidade</option></select></label></div><p id="territoryNote"></p><div class="scroll" id="table"></div><small>Alocações em votos são expectativas fracionárias; exibição arredondada não altera o cálculo. Outros destinos incluem brancos, nulos, abstenção e ajuste de universo. Permanência dos finalistas aparece na coluna do próprio candidato.</small><p><button id="csv">Baixar tabela do recorte em CSV</button></p></section>
<section><h2>Histogramas por estado · faixas de 5 pontos percentuais</h2><p>Em cada seção com votos para a candidatura selecionada: percentual desses votos alocado ao destino. Faixas [0,5), [5,10), …, [95,100]. Cada seção é uma observação; também é possível ponderar pelos votos da origem.</p><div class="controls"><label>Candidato <select id="candidate"></select></label><label>Destino <select id="destination"><option value="1">Flávio</option><option value="0">Lula</option></select></label><label>Eixo vertical <select id="weight"><option value="urnas">Número de seções</option><option value="votos_origem">Votos da origem nas seções</option></select></label></div><p>Os histogramas descrevem exclusivamente o cenário de permanência máxima e rateio residual. A escala vertical é própria de cada estado; consulte a altura e o valor ao tocar a barra.</p><div id="histograms" class="grid"></div></section>
<section><h2>Limites condicionais e sensibilidade da candidatura</h2><p id="limits"></p><div class="scroll" id="bounds"></div></section><section><h2>Rastreabilidade</h2><p>Fontes: arquivos secoes-UF.json.gz e candidatos-secao-UF.json em dados/2026 do repositório fabiooliveira-source/paineleleitoral-2026. Referência de versão: 104b8adbecbee2261b9b4883eb46ef6352996dd4. Chave de pareamento: UF + código municipal TSE + zona + seção. Uma linha não deve ser confundida automaticamente com um equipamento físico único.</p><p>Confiança alta na conciliação matemática; baixa para interpretar os fluxos como comportamento real dos eleitores.</p><button id="json">Baixar dados agregados e hashes das fontes</button></section></main><script>const DATA=__DATA__;
const $=x=>document.getElementById(x),fmt=x=>Math.round(x).toLocaleString('pt-BR'),pc=(n,b)=>b?(100*n/b).toFixed(2).replace('.',',')+'%':'—';
function states(){const t=$('territory').value;return DATA.states.filter(s=>t==='BR'||t==='BRonly'&&s.uf!=='ZZ'||s.uf===t)}
function sum(rows,key){const v=rows[0][key];if(Array.isArray(v[0]))return v.map((r,i)=>r.map((_,j)=>rows.reduce((a,s)=>a+s[key][i][j],0)));return v.map((_,i)=>rows.reduce((a,s)=>a+s[key][i],0))}
function table(headers,rows){return '<table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function renderTable(){const ss=states(),a=sum(ss,'first'),m=sum(ss,$('model').value);$('table').innerHTML=table(['Candidato · 1º turno','Votos de origem','→ Flávio · votos','→ Flávio · %','→ Lula · votos','→ Lula · %','Outros destinos · %'],DATA.codes.map((c,i)=>[DATA.origins[i],fmt(a[i]),fmt(m[i][1]),pc(m[i][1],a[i]),fmt(m[i][0]),pc(m[i][0],a[i]),pc(m[i].slice(2).reduce((x,y)=>x+y,0),a[i])]));$('territoryNote').textContent=fmt(ss.reduce((a,s)=>a+s.included_sections,0))+' seções incluídas de '+fmt(ss.reduce((a,s)=>a+s.total_sections,0))+' avaliadas no território. Percentuais ponderados pelos votos da origem.';renderBounds()}
function renderBounds(){const ss=states(),i=DATA.codes.indexOf($('candidate').value),a=sum(ss,'first'),m=sum(ss,'matrix'),alt=sum(ss,'independence'),lo=sum(ss,'lower'),hi=sum(ss,'upper');$('limits').textContent=DATA.origins[i]+' · '+fmt(a[i])+' votos no primeiro turno no recorte da tabela.';$('bounds').innerHTML=table(['Destino','Principal','Independência','Mínimo condicional','Máximo condicional'],[1,0].map(j=>[DATA.destinations[j],pc(m[i][j],a[i]),pc(alt[i][j],a[i]),pc(lo[i][j],a[i]),pc(hi[i][j],a[i])]))}
function renderHist(){const code=$('candidate').value,j=+$('destination').value,w=$('weight').value;let ss=DATA.states;$('histograms').innerHTML=ss.map(s=>{const h=s.histograms[code][j][w],max=Math.max(1,...h),count=h.reduce((a,b)=>a+b,0);let svg='<svg viewBox="0 0 340 205" role="img" aria-label="Histograma '+s.uf+'"><text x="35" y="15" font-size="11">Máximo: '+fmt(max)+'</text><line x1="35" y1="165" x2="330" y2="165" stroke="#8a9ba8"/>';h.forEach((v,k)=>{const height=130*v/max;svg+='<rect tabindex="0" x="'+(36+k*14.5)+'" y="'+(165-height)+'" width="12" height="'+Math.max(.3,height)+'" fill="'+(j===1?'#15835b':'#c33348')+'"><title>'+k*5+'–'+(k+1)*5+'%: '+fmt(v)+'</title></rect>'});for(let k=0;k<=4;k++)svg+='<text x="'+(35+k*72.5)+'" y="185" font-size="11">'+k*25+'%</text>';svg+='</svg>';return '<article class="card"><h3>'+s.uf+(s.uf==='ZZ'?' · Exterior':'')+'</h3><small>'+fmt(s.included_sections)+' / '+fmt(s.total_sections)+' seções incluídas · '+fmt(count)+' '+(w==='urnas'?'seções com votos da origem':'votos da origem')+'</small>'+svg+'</article>'}).join('');renderBounds()}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
for(const s of DATA.states)$('territory').add(new Option(s.uf==='ZZ'?'Exterior':s.uf,s.uf));DATA.codes.forEach((c,i)=>$('candidate').add(new Option(DATA.origins[i]+' · '+c,c)));$('candidate').value='70';for(const id of ['territory','model'])$(id).onchange=renderTable;for(const id of ['candidate','destination','weight'])$(id).onchange=renderHist;
$('csv').onclick=()=>{const ss=states(),a=sum(ss,'first'),m=sum(ss,$('model').value);download('migracao-simulada-por-candidato.csv','\uFEFF'+[['Candidato','Base_1t','Flavio_simulado','Pct_Flavio','Lula_simulado','Pct_Lula','Outros_pct'],...DATA.codes.map((c,i)=>[DATA.origins[i],a[i],m[i][1],pc(m[i][1],a[i]),m[i][0],pc(m[i][0],a[i]),pc(m[i].slice(2).reduce((x,y)=>x+y,0),a[i])])].map(r=>r.join(';')).join('\n'),'text/csv;charset=utf-8')};$('json').onclick=()=>download('migracao-brasil-dados.json',JSON.stringify(DATA,null,2),'application/json');
const au=DATA.audit;$('kpis').innerHTML=[['Seções avaliadas',au.sections_evaluated],['Incluídas',au.sections_included],['Excluídas',au.sections_evaluated-au.sections_included],['Recorte estrito',au.strictly_comparable_sections]].map(([n,v])=>'<div><b>'+fmt(v)+'</b>'+n+'</div>').join('');$('audit').textContent='Somas por origem e destino conciliadas antes do arredondamento; maior resíduo numérico nacional inferior a 0,00001 voto. Pesos dos histogramas conciliados com os votos de origem. 43 exclusões no exterior por dados não conferidos. Recorte estrito: '+fmt(au.strictly_comparable_sections)+' seções; o cenário amplo inclui mudanças cadastrais explicitamente.';renderTable();renderHist();</script></html>'''
(P/'migracao-brasil.html').write_text(html.replace('__DATA__',json.dumps(D,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')))
print(json.dumps(D['audit']));print('generated HTML', (P/'migracao-brasil.html').stat().st_size)
